      auto x = util::f16_to_f32_simd(a);
      auto n = util::stdx::static_simd_cast<
          util::stdx::fixed_size_simd<int, util::native<float>::size()>>(
          (util::stdx::static_simd_cast<util::native<int32_t>>(b) << 16) >> 16);
